/// <summary>
/// This is a service class
/// CB197_salesOrderReturnsAndClaims
/// </summary>
final class METReturnOrderDispositionCodeUpdService extends METSysOperationService
{
    private guid topPickingProcessId;    

}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METReturnOrderDispositionCodeUpdTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METReturnOrderDispositionCodeUpdTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:ReturnOrderPostCreationProcessing";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METReturnOrderDispositionCodeUpdContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    super();

    METReturnOrderDispositionCodeUpdContract contract = dataContract as METReturnOrderDispositionCodeUpdContract;
    Query query = contract.getQuery();

    this.processSalesOrders(query);

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METReturnOrderDispositionCodeUpdContract contract = _taskDataContract as METReturnOrderDispositionCodeUpdContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METReturnOrderDispositionCodeUpdContract();
}

/// <summary>
/// Process return sales orders from the query and insert SO number in <c>METReturnOrderDispositionCodeUpdQueue</c>
/// </summary>
/// <param name = "_query"><c>Query</c> object</param>
void processSalesOrders(Query _query)
{
    SalesTable returnSalesTable;
    RecordInsertList returnOrderDispositionCodeUpdQueueList;
    #OCCRetryCount

    METReturnOrderDispositionCodeUpdQueue::cleanUpPostSalesOrderCreationProcessingQueue();
    returnOrderDispositionCodeUpdQueueList = new RecordInsertList(tableNum(METReturnOrderDispositionCodeUpdQueue));
    topPickingProcessId = newGuid();

    QueryRun qr = new QueryRun(_query);

    while (qr.next())
    {
        returnSalesTable = qr.get(tableNum(SalesTable));

        this.processSingleReturnSalesOrder(returnOrderDispositionCodeUpdQueueList, returnSalesTable.SalesId);
    }

    this.insertIntoTopPickingQueue(returnOrderDispositionCodeUpdQueueList);
}

/// <summary>
/// Adding sales order to process into the RecordInsertList
/// </summary>
/// <param name = "_returnSalesQueueList"><c>RecordInsertList</c> object</param>
/// <param name = "_salesId">Sales order number</param>
private void addToReturnOrderDispositionCodeUpdQueueList(RecordInsertList _returnSalesQueueList, SalesIdBase _salesId)
{
    METReturnOrderDispositionCodeUpdQueue postRecord;
    postRecord.ProcessId = this.topPickingProcessId;
    postRecord.SalesId = _salesId;

    _returnSalesQueueList.add(postRecord);
}

/// <summary>
/// Buld insert from RecordInsertList into <c>METSalesOrderCreditMgmtCheckQueue</c>
/// </summary>
/// <param name = "_returnOrderDispositionCodeUpdQueueLists">RecordInsertList to bulk insert</param>
private void insertIntoTopPickingQueue(RecordInsertList _returnOrderDispositionCodeUpdQueueList)
{
    _returnOrderDispositionCodeUpdQueueList.insertDatabase();
}

/// <summary>
/// Adding sales order to list
/// </summary>
/// <param name = "_returnOrderDispositionCodeUpdQueueList">List of sales orders queue</param>
/// <param name = "_salesId">salesid</param>
private void processSingleReturnSalesOrder(RecordInsertList _returnOrderDispositionCodeUpdQueueList, SalesId _salesId)
{
    #define.RetryNum(5);

    try
    {
        this.addToReturnOrderDispositionCodeUpdQueueList(_returnOrderDispositionCodeUpdQueueList, _salesId);
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}
